#include <zephyr/logging/log.h>
#include <zephyr/sys/p4wq.h>
#include <zephyr/kernel.h>
#include <zephyr/kernel_structs.h>
#include <wait_q.h>

LOG_MODULE_REGISTER(p4wq, CONFIG_LOG_DEFAULT_LEVEL);

struct k_p4wq_work *rb_work(struct rbnode *n)
{
	return CONTAINER_OF(n, struct k_p4wq_work, rbnode);
}

/* Less-than comparator where "less" means "higher priority": first by
 * the integer priority value, then by the deadline, using the memory
 * address as a tie-breaker.
 */
static bool rb_lessthan(struct rbnode *a, struct rbnode *b)
{
	struct k_p4wq_work *wa = rb_work(a), *wb = rb_work(b);

	if (wa->priority != wb->priority) {
		return wa->priority > wb->priority;
	}

	if (wa->deadline != wb->deadline) {
		return wa->deadline - wb->deadline < 0;
	}

	return (uintptr_t)a < (uintptr_t)b;
}

static void set_prio(struct k_thread *th, struct k_p4wq_work *w)
{
	/* Standardized conversion between integer priority and waitq
	 * priority, should really be shared with zephyr/kernel/sched.c
	 */
	int prio = w->priority < 0 ? 1 - w->priority : -(w->priority + 1);

	/* Never use the outermost priorities on each side (highest
	 * cooperative and lowest preemptible)
	 */
	prio = CLAMP(prio, -CONFIG_NUM_COOP_PRIORITIES + 1,
		     CONFIG_NUM_PREEMPT_PRIORITIES - 2);

	k_thread_priority_set(th, prio);
	k_thread_deadline_set(th, w->deadline);
}

/* Must be called locked.  Weird call signature to accommodate
 * static_threads_foreach()
 */
static void thread_Look_for_work(const struct k_thread *cth, void *user_data)
{
	struct k_thread *th = (struct k_thread *)cth;
	struct k_p4wq *queue = user_data;
	struct rbnode *n = rb_get_min(&queue->queue);

	if (n != NULL) {
		struct k_p4wq_work *w = rb_work(n);

		rb_remove(&queue->queue, n);
		w->thread = th;
		sys_dlist_append(&queue->active, &w->dlnode);
		set_prio(th, w);

		arch_thread_return_value_set(th, 0);
		z_pend_thread(th, &queue->waitq, K_FOREVER);
	}
}

static FUNC_NORETURN void p4wq_loop(void *p0, void *p1, void *p2)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	struct k_p4wq *queue = p0;

	while (true) {
		k_spinlock_key_t k = k_spin_lock(&queue->lock);
		struct rbnode *n = rb_get_min(&queue->queue);

		if (n != NULL) {
			struct k_p4wq_work *w = rb_work(n);
			bool sync = w->sync;

			rb_remove(&queue->queue, n);
			w->thread = _current;
			sys_dlist_append(&queue->active, &w->dlnode);
			set_prio(_current, w);
			k_spin_unlock(&queue->lock, k);

			w->handler(w);

			k = k_spin_lock(&queue->lock);
			sys_dlist_remove(&w->dlnode);
			w->thread = NULL;
			if (!(queue->flags & K_P4WQ_USER_CPU_MASK)) {
				uintptr_t mask = (uintptr_t)_current->arch.custom_data;

				for (int i = 0; i < arch_num_cpus(); i++) {
					if (mask & BIT(i)) {
						queue->done_handler(w);
					}
				}
			}
			k_spin_unlock(&queue->lock, k);

			if (sync) {
				k_sem_give(&w->done_sem);
			} else if (queue->done_handler != NULL) {
				queue->done_handler(w);
			}
		} else {
			/* Drop to lowest priority while waiting so we
			 * can't steal a CPU on initial wakeup before
			 * our target priority is set
			 */
			k_thread_priority_set(_current, K_LOWEST_APPLICATION_THREAD_PRIO);
			z_pend_curr(&queue->lock, k, &queue->waitq, K_FOREVER);
		}
	}
}

void k_p4wq_enable_static_thread(struct k_p4wq *queue, struct k_thread *thread,
				 uint32_t cpu_mask)
{
	unsigned int num_cpus = arch_num_cpus();

	for (int i = 0; i < num_cpus; i++) {
		if ((queue->flags & K_P4WQ_USER_CPU_MASK) && (cpu_mask & BIT(i))) {
			k_thread_cpu_mask_enable(thread, i);
		}
	}

	k_thread_start(thread);
}

void k_p4wq_add_thread(struct k_p4wq *queue, struct k_thread *thread,
		       k_thread_stack_t *stack,
		       size_t stack_size)
{
	k_thread_create(thread, stack, stack_size,
			p4wq_loop, queue, NULL, NULL,
			K_HIGHEST_APPLICATION_THREAD_PRIO, 0,
			(queue->flags & K_P4WQ_DELAYED_START) ? K_FOREVER : K_NO_WAIT);
}

void k_p4wq_init(struct k_p4wq *queue)
{
	memset(queue, 0, sizeof(*queue));
	queue->queue.lessthan_fn = rb_lessthan;
	z_waitq_init(&queue->waitq);
	sys_dlist_init(&queue->active);
}

void k_p4wq_submit(struct k_p4wq *queue, struct k_p4wq_work *item)
{
	k_spinlock_key_t k = k_spin_lock(&queue->lock);

	if (item->sync) {
		k_sem_init(&item->done_sem, 0, 1);
	}

	/* Item is already in the queue, must remove to change priority */
	if (item->queue != NULL) {
		if (item->thread == NULL) {
			rb_remove(&queue->queue, &item->rbnode);
		} else {
			set_prio(item->thread, item);
			goto out;
		}
	} else {
		__ASSERT_NO_MSG(item->thread == NULL);
	}

	rb_insert(&queue->queue, &item->rbnode);
	item->queue = queue;

	/* If there were any idle threads, wake one up.  Note that on
	 * SMP this might wake up the "wrong" thread if the work item
	 * is lower priority than what's already running on other
	 * CPUs.  Getting this genuinely right requires teaching the
	 * scheduler about waitq thread affinity, which it doesn't
	 * comprehend right now.  Just wake up all of them in the
	 * custom mask case.
	 */
	struct k_thread *th = z_unpend_first_thread(&queue->waitq);

	if (th != NULL) {
		z_ready_thread(th);

		if (queue->flags & K_P4WQ_USER_CPU_MASK) {
			while ((th = z_unpend_first_thread(&queue->waitq)) != NULL) {
				z_ready_thread(th);
			}
		}

		z_reschedule(&queue->lock, k);
		return;
	}

	/* Otherwise, see if we can preempt a running item (recall
	 * "lessthan" means "higher priority").  Look for the lowest
	 * priority thread in the active list and unpend a sleeping
	 * thread if there is one.  Looking at the active list in
	 * human time is fine, it's bounded by the number of threads.
	 */
	struct k_p4wq_work * victim = NULL, *w;

	SYS_DLIST_FOR_EACH_CONTAINER(&queue->active, w, dlnode) {
		if (victim == NULL || rb_lessthan(&victim->rbnode, &w->rbnode)) {
			victim = w;
		}
	}

	if (victim != NULL && rb_lessthan(&item->rbnode, &victim->rbnode)) {
		/* Preempt!  Set the victim's priority to the max so
		 * it isn't picked by the scheduler until our new
		 * item's thread has had a chance to run.
		 */
	}

out:
	k_spin_unlock(&queue->lock, k);
}

bool k_p4wq_cancel(struct k_p4wq *queue, struct k_p4wq_work *item)
{
	k_spinlock_key_t k = k_spin_lock(&queue->lock);
	bool ret = item->queue != NULL && item->thread == NULL;

	if (ret) {
		rb_remove(&queue->queue, &item->rbnode);
		item->queue = NULL;
	}

	k_spin_unlock(&queue->lock, k);
	return ret;
}

int k_p4wq_wait(struct k_p4wq_work *work, k_timeout_t timeout)
{
	if (work->sync) {
		return k_sem_take(&work->done_sem, timeout);
	}
	return 0;
}
